import { useEffect, useState } from 'react';
import { assembliesApi, customFieldsApi } from '../services/api';
import type { Assembly, CustomFieldDefinition, CustomFieldValue } from '../types';
import { canEdit, isAdmin } from '../stores/auth';
import { Modal, ConfirmModal } from '../components/Modal';
import { getNextVersion } from '../constants';
import { useDataStore } from '../stores/data';
import { formatDateTime } from '../utils/date';

interface AssemblyFormData {
  code: string;
  name: string;
  spec: string;
  version: string;
  status: string;
  remark: string;
}

const initialFormData: AssemblyFormData = {
  code: '',
  name: '',
  spec: '',
  version: 'A',
  status: 'draft',
  remark: '',
};

export default function Components() {
  const [assemblies, setAssemblies] = useState<Assembly[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('');

  const [modalOpen, setModalOpen] = useState(false);
  const [editingAssembly, setEditingAssembly] = useState<Assembly | null>(null);
  const [formData, setFormData] = useState<AssemblyFormData>(initialFormData);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // 详情弹窗
  const [viewingAssembly, setViewingAssembly] = useState<Assembly | null>(null);
  const [viewingCustomDefs, setViewingCustomDefs] = useState<CustomFieldDefinition[]>([]);
  const [viewingCustomValues, setViewingCustomValues] = useState<Record<string, any>>({});

  // 从 store 订阅数据
  const storeAssemblies = useDataStore((s) => s.assemblies);

  // Custom fields
  const [customFieldDefs, setCustomFieldDefs] = useState<CustomFieldDefinition[]>([]);
  const [customFieldValues, setCustomFieldValues] = useState<Record<string, any>>({});
  const [loadingCustomFields, setLoadingCustomFields] = useState(false);

  useEffect(() => {
    loadAssemblies();
  }, [search, status, storeAssemblies]);

  const loadAssemblies = async () => {
    const localAssemblies = useDataStore.getState().assemblies;
    if (localAssemblies.length > 0) {
      setAssemblies(localAssemblies);
      setLoading(false);
      return;
    }
    try {
      setLoading(true);
      const response = await assembliesApi.list({ search, status });
      setAssemblies(Array.isArray(response.data) ? response.data : (response.data.items || []));
    } catch (error) {
      console.error('加载部件失败', error);
    } finally {
      setLoading(false);
    }
  };

  const loadCustomFields = async () => {
    const localDefs = useDataStore.getState().customFieldDefs;
    if (localDefs.length > 0) {
      setCustomFieldDefs(localDefs.filter((d: CustomFieldDefinition) =>
        d.applies_to?.includes('component')
      ));
      setLoadingCustomFields(false);
      return;
    }
    try {
      setLoadingCustomFields(true);
      const response = await customFieldsApi.listDefinitions();
      const defs = (response.data || []).filter((d: CustomFieldDefinition) =>
        d.applies_to?.includes('component')
      );
      setCustomFieldDefs(defs);
    } catch (error) {
      console.error('加载自定义字段失败', error);
    } finally {
      setLoadingCustomFields(false);
    }
  };

  const loadCustomFieldValues = async (assemblyId: string) => {
    try {
      const response = await customFieldsApi.getValues('component', assemblyId);
      const values: Record<string, any> = {};
      (response.data || []).forEach((v: CustomFieldValue) => {
        values[v.field_id] = v.value;
      });
      setCustomFieldValues(values);
    } catch (error) {
      console.error('加载自定义字段值失败', error);
    }
  };

  const handleAdd = () => {
    setEditingAssembly(null);
    setFormData(initialFormData);
    setCustomFieldValues({});
    loadCustomFields();
    setModalOpen(true);
  };

  const handleEdit = async (assembly: Assembly) => {
    setEditingAssembly(assembly);
    setFormData({
      code: assembly.code,
      name: assembly.name,
      spec: assembly.spec || '',
      version: assembly.version || 'A',
      status: assembly.status,
      remark: assembly.remark || '',
    });
    await loadCustomFields();
    await loadCustomFieldValues(assembly.id);
    setModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setSaveError(null);

    const data = {
      code: formData.code,
      name: formData.name,
      spec: formData.spec || undefined,
      version: formData.version || undefined,
      status: formData.status,
      remark: formData.remark || undefined,
    };

    try {
      let newAssembly: Assembly | null = null;
      if (editingAssembly) {
        const res = await assembliesApi.update(editingAssembly.id, data);
        newAssembly = res.data;
        useDataStore.getState().setAssemblies(
          useDataStore.getState().assemblies.map(a => a.id === editingAssembly.id ? newAssembly! : a)
        );
      } else {
        const res = await assembliesApi.create(data);
        newAssembly = res.data;
        useDataStore.getState().setAssemblies([...useDataStore.getState().assemblies, newAssembly!]);
      }

      const fieldValues = customFieldDefs.map(def => ({
        field_id: def.id,
        value: customFieldValues[def.id] ?? null,
      })).filter(fv => fv.value !== null && fv.value !== '');
      
      if (fieldValues.length > 0) {
        await customFieldsApi.setValues('component', newAssembly!.id, fieldValues);
      }

      setModalOpen(false);
    } catch (error: any) {
      const detail = error.response?.data?.detail;
      setSaveError(Array.isArray(detail) ? detail.map((e: any) => e.msg || JSON.stringify(e)).join('; ') : (typeof detail === 'string' ? detail : (editingAssembly ? '更新失败，请重试' : '创建失败，请检查网络或数据是否已存在')));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await assembliesApi.delete(deleteId);
      setDeleteId(null);
      useDataStore.getState().setAssemblies(
        useDataStore.getState().assemblies.filter(a => a.id !== deleteId)
      );
    } catch (error) {
      alert('删除失败');
    }
  };

  const handleView = async (assembly: Assembly) => {
    setViewingAssembly(assembly);
    const allDefs = useDataStore.getState().customFieldDefs;
    const asmDefs = allDefs.filter((d: CustomFieldDefinition) => d.applies_to?.includes('component'));
    setViewingCustomDefs(asmDefs);
    try {
      const res = await customFieldsApi.getValues('component', assembly.id);
      const values: Record<string, any> = {};
      (res.data || []).forEach((v: CustomFieldValue) => {
        values[v.field_id] = v.value;
      });
      setViewingCustomValues(values);
    } catch {
      setViewingCustomValues({});
    }
  };

  const getStatusTag = (s: string) => {
    const tags: Record<string, { label: string; class: string }> = {
      draft: { label: '草稿', class: 'bg-blue-100 text-blue-800' },
      frozen: { label: '冻结', class: 'bg-orange-100 text-orange-800' },
      released: { label: '发布', class: 'bg-green-100 text-green-800' },
      obsolete: { label: '作废', class: 'bg-red-100 text-red-800' },
    };
    return tags[s] || { label: s, class: 'bg-gray-100 text-gray-800' };
  };

  const renderCustomFieldInput = (def: CustomFieldDefinition) => {
    const value = customFieldValues[def.id] ?? '';
    const handleChange = (v: any) => {
      setCustomFieldValues({ ...customFieldValues, [def.id]: v });
    };

    if (def.field_type === 'select' && def.options?.length) {
      return (
        <select
          value={value}
          onChange={(e) => handleChange(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
        >
          <option value="">请选择</option>
          {def.options.map(opt => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      );
    }
    if (def.field_type === 'number') {
      return (
        <input
          type="number"
          value={value}
          onChange={(e) => handleChange(e.target.value ? Number(e.target.value) : null)}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
        />
      );
    }
    return (
      <input
        type="text"
        value={value}
        onChange={(e) => handleChange(e.target.value)}
        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
      />
    );
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-semibold">部件管理</h2>
        {canEdit() && (
          <button
            onClick={handleAdd}
            className="px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700"
          >
            + 新增部件
          </button>
        )}
      </div>

      <div className="flex gap-2 mb-4">
        <input
          type="text"
          placeholder="搜索件号/中文名称..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 flex-1"
        />
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
        >
          <option value="">全部状态</option>
          <option value="draft">草稿</option>
          <option value="frozen">冻结</option>
          <option value="released">发布</option>
          <option value="obsolete">作废</option>
        </select>
      </div>

      <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              <th className="px-4 py-3 text-left text-sm font-medium text-gray-500">件号</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-gray-500">中文名称</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-gray-500">规格型号</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-gray-500">版本</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-gray-500">状态</th>
              <th className="px-4 py-3 text-right text-sm font-medium text-gray-500">操作</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {loading ? (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-gray-500">加载中...</td>
              </tr>
            ) : assemblies.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-gray-500">暂无数据</td>
              </tr>
            ) : (
              assemblies.map((assembly) => (
                <tr key={assembly.id} className="hover:bg-gray-50 cursor-pointer" onClick={() => handleView(assembly)}>
                  <td className="px-4 py-3 text-sm font-medium">{assembly.code}</td>
                  <td className="px-4 py-3 text-sm">{assembly.name}</td>
                  <td className="px-4 py-3 text-sm text-gray-500">{assembly.spec || '-'}</td>
                  <td className="px-4 py-3 text-sm text-gray-500">{assembly.version || '-'}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-1 text-xs rounded-full ${getStatusTag(assembly.status).class}`}>
                      {getStatusTag(assembly.status).label}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right" onClick={(e) => e.stopPropagation()}>
                    <button onClick={() => handleEdit(assembly)} className="text-primary-600 hover:text-primary-800 mr-3">编辑</button>
                    {isAdmin() && (
                      <button onClick={() => setDeleteId(assembly.id)} className="text-red-600 hover:text-red-800">删除</button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal
        open={modalOpen}
        title={editingAssembly ? '编辑部件' : '新增部件'}
        onClose={() => setModalOpen(false)}
        width="lg"
      >
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">件号 <span className="text-red-500">*</span></label>
              <input
                type="text"
                value={formData.code}
                onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">中文名称 <span className="text-red-500">*</span></label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">规格型号</label>
              <input
                type="text"
                value={formData.spec}
                onChange={(e) => setFormData({ ...formData, spec: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">版本</label>
              <input
                type="text"
                value={formData.version}
                onChange={(e) => setFormData({ ...formData, version: e.target.value.toUpperCase() })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
                placeholder="如: A, B, V1.0"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">状态</label>
            <select
              value={formData.status}
              onChange={(e) => setFormData({ ...formData, status: e.target.value })}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
            >
              <option value="draft">草稿</option>
              <option value="frozen">冻结</option>
              <option value="released">发布</option>
              <option value="obsolete">作废</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">备注</label>
            <textarea
              value={formData.remark}
              onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
              rows={3}
              placeholder="可选"
            />
          </div>

          {/* Custom Fields */}
          {customFieldDefs.length > 0 && (
            <div className="border-t pt-4">
              <h4 className="text-sm font-medium text-gray-700 mb-3">自定义字段</h4>
              {loadingCustomFields ? (
                <div className="text-sm text-gray-500">加载中...</div>
              ) : (
                <div className="space-y-3">
                  {customFieldDefs.map(def => (
                    <div key={def.id}>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        {def.name}
                        {def.is_required && <span className="text-red-500 ml-1">*</span>}
                      </label>
                      {renderCustomFieldInput(def)}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {saveError && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-2 rounded-lg text-sm">
              {saveError}
            </div>
          )}

          <div className="flex justify-between items-center gap-2 pt-4 border-t">
            <div>
              {editingAssembly && (editingAssembly.status === 'released' || editingAssembly.status === 'obsolete') && (
                <button
                  type="button"
                  onClick={() => setFormData({ ...formData, version: getNextVersion(formData.version) })}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                  title="升版"
                >
                  升版
                </button>
              )}
            </div>
            <div className="flex gap-2">
              <button type="button" onClick={() => setModalOpen(false)} className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50">取消</button>
              <button type="submit" disabled={saving} className="px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 disabled:opacity-50">
                {saving ? '保存中...' : '保存'}
              </button>
            </div>
          </div>
        </form>
      </Modal>

      <ConfirmModal
        open={!!deleteId}
        title="确认删除"
        content="确定要删除该部件吗？此操作不可撤销。"
        confirmText="删除"
        cancelText="取消"
        type="danger"
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />

      {/* 部件详情弹窗 */}
      <Modal
        open={!!viewingAssembly}
        title="部件详情"
        onClose={() => setViewingAssembly(null)}
        width="lg"
      >
        {viewingAssembly && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">件号</label>
                <div className="text-sm font-medium">{viewingAssembly.code}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">中文名称</label>
                <div className="text-sm">{viewingAssembly.name}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">规格型号</label>
                <div className="text-sm">{viewingAssembly.spec || '-'}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">版本</label>
                <div className="text-sm">{viewingAssembly.version || '-'}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">状态</label>
                <span className={`inline-block px-2 py-1 text-xs rounded-full ${getStatusTag(viewingAssembly.status).class}`}>
                  {getStatusTag(viewingAssembly.status).label}
                </span>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">备注</label>
                <div className="text-sm">{viewingAssembly.remark || '-'}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">创建时间</label>
                <div className="text-sm">{formatDateTime(viewingAssembly.created_at)}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">更新时间</label>
                <div className="text-sm">{formatDateTime(viewingAssembly.updated_at)}</div>
              </div>
            </div>

            {/* 自定义字段 */}
            {viewingCustomDefs.length > 0 && (
              <div className="border-t pt-4">
                <h4 className="text-sm font-medium text-gray-700 mb-3">自定义字段</h4>
                <div className="grid grid-cols-2 gap-4">
                  {viewingCustomDefs.map(def => (
                    <div key={def.id}>
                      <label className="block text-xs font-medium text-gray-500 mb-1">{def.name}</label>
                      <div className="text-sm">
                        {def.field_type === 'select'
                          ? (def.options || []).find(o => o === viewingCustomValues[def.id]) || viewingCustomValues[def.id] || '-'
                          : (viewingCustomValues[def.id] ?? '-')}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </Modal>
    </div>
  );
}